window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-13db19d454506a09"]={"versions": [{"id": "FIG-13db19d454506a09", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd Run Sequence</code>) im Kontext des AUTOSAR ECU State Managers (EcuM). Das Diagramm stellt die High-Level-Ablaufsequenz des RUN-Zustands (<code>RUN State Sequence</code>) und dessen Verknüpfung mit vorangehenden sowie nachfolgenden Phasen dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Lebenslinien / Entitäten:</strong>\n<ul class=\"fig-list\"><li><code>EcuM::EcuM</code>: Instanz des ECU State Managers als zentrale Steuerungslebenslinie mit Aktivierungsbalken.\n</li><li><code>RTE::RTE</code>: Runtime Environment als Kommunikationspartner.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Operationen:</strong>\n<ul class=\"fig-list\"><li><code>RTE_Write_NotifyMode_ModeIndex(Instance, RUN)</code>: Synchrone Benachrichtigung an die RTE über den Wechsel in den RUN-Modus.\n</li></ul>\n</li><li><strong>Interaktionsreferenzen (<code>ref</code>):</strong>\n<ul class=\"fig-list\"><li><code>Power Up Sequence</code>\n</li><li><code>Wakeup Sequence</code>\n</li><li><code>Run Sequence II</code> (über Notiz als „Corresponds to RUN II“ annotiert)\n</li><li><code>Run Sequence III</code> (über Notiz als „Corresponds to RUN III“ annotiert)\n</li><li><code>Shutdown Sequence</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Eintritt (<code>alt Entry of RUN</code>):</strong>\n<ul class=\"fig-list\"><li>Zweig <code>[from STARTUP]</code>: Ausführung der Referenz <code>Power Up Sequence</code>, die synchron in eine kurze Aktivierung des EcuM übergeht.\n</li><li>Zweig <code>[from WAKEUP]</code>: Ausführung der Referenz <code>Wakeup Sequence</code>, die in die Hauptaktivierung des EcuM im RUN-Zustand mündet.\n</li></ul>\n</li><li><strong>Hauptschleife (<code>loop while Run requests pending</code>):</strong>\n<ul class=\"fig-list\"><li>Solange RUN-Anforderungen anstehen, ruft der EcuM synchron <code>RTE_Write_NotifyMode_ModeIndex(Instance, RUN)</code> auf der RTE auf.\n</li><li>Anschließend erfolgt ein synchroner Aufruf (<code>call</code>) der Referenzsequenz <code>Run Sequence II</code> mit Rückkehr (<code>return</code>).\n</li><li>Darauf folgt ein synchroner Aufruf (<code>call</code>) der Referenzsequenz <code>Run Sequence III</code> mit Rückkehr (<code>return</code>).\n</li></ul>\n</li><li><strong>Verlassen des RUN-Zustands:</strong>\n<ul class=\"fig-list\"><li>Nach Beendigung der Schleife geht der EcuM mit <code>continue with</code> in die Referenz <code>Shutdown Sequence</code> über.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die normative Kontrollflussstruktur des EcuM im RUN-Zustand. Vor Eintritt in die zyklischen RUN-Phasen (RUN II und RUN III) ist die RTE über den Moduswechsel zu informieren. Die Fortführung in den Shutdown setzt zwingend voraus, dass keine RUN-Requests mehr anhängig sind. Die referenzierten Sequenzen RUN II und RUN III werden in untergeordneten Detaildiagrammen spezifiziert.</p>"}, {"id": "FIG-ef066f3b0575df3a", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm ohne äußeren Rahmen im Kontext des AUTOSAR ECU State Managers (EcuM). Das Diagramm stellt die High-Level-Ablaufsequenz des RUN-Zustands (<code>RUN State Sequence</code>) und dessen Verknüpfung mit vorangehenden sowie nachfolgenden Phasen dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Lebenslinien / Entitäten:</strong>\n<ul class=\"fig-list\"><li><code>«module» EcuM::EcuM</code>: Modul des ECU State Managers als alleinige dargestellte Lebenslinie mit Aktivierungsbalken.\n</li></ul>\n</li><li><strong>Interaktionsreferenzen (<code>ref</code>):</strong>\n<ul class=\"fig-list\"><li><code>Power Up Sequence</code>\n</li><li><code>Wakeup Sequence</code>\n</li><li><code>Run Sequence II</code> (über Notiz als „Corresponds to RUN II“ annotiert)\n</li><li><code>Run Sequence III</code> (über Notiz als „Corresponds to RUN III“ annotiert)\n</li><li><code>Shutdown Sequence</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Eintritt (<code>alt Entry of RUN</code>):</strong>\n<ul class=\"fig-list\"><li>Zweig <code>[from STARTUP]</code>: Ausführung der Referenz <code>Power Up Sequence</code>, die synchron in eine kurze Aktivierung des EcuM übergeht.\n</li><li>Zweig <code>[from WAKEUP]</code>: Ausführung der Referenz <code>Wakeup Sequence</code>, die in die Hauptaktivierung des EcuM im RUN-Zustand mündet.\n</li></ul>\n</li><li><strong>Hauptschleife (<code>loop While RUN requests pending</code>):</strong>\n<ul class=\"fig-list\"><li>Solange RUN-Anforderungen anstehen, führt der EcuM synchron den Aufruf <code>call()</code> zur Referenzsequenz <code>Run Sequence II</code> aus und empfängt die Rückkehr.\n</li><li>Anschließend erfolgt der synchrone Aufruf <code>call()</code> zur Referenzsequenz <code>Run Sequence III</code> mit Rückkehr.\n</li></ul>\n</li><li><strong>Verlassen des RUN-Zustands:</strong>\n<ul class=\"fig-list\"><li>Nach Verlassen der Schleife geht der EcuM über <code>continue with()</code> direkt in die Referenz <code>Shutdown Sequence</code> über.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die übergeordnete Kontrollflussstruktur des EcuM im RUN-Zustand rein intern auf Modulebene ohne explizite Interaktionspartner. Die Fortführung in den Shutdown setzt voraus, dass keine RUN-Requests mehr anhängig sind. Die referenzierten Sequenzen RUN II und RUN III werden in separaten Sub-Sequenzdiagrammen detailliert.</p>"}, {"id": "FIG-2e8eec89d8f7369c", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd EcuM_Run Sequence</code>) im Kontext des AUTOSAR ECU State Managers (EcuM). Das Diagramm stellt die High-Level-Ablaufsequenz des RUN-Zustands (<code>RUN State Sequence</code>) und dessen Verknüpfung mit vorangehenden sowie nachfolgenden Phasen dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Lebenslinien / Entitäten:</strong>\n<ul class=\"fig-list\"><li><code>«module» EcuM</code>: Modul des ECU State Managers als alleinige dargestellte Lebenslinie mit Aktivierungsbalken.\n</li></ul>\n</li><li><strong>Interaktionsreferenzen (<code>ref</code>):</strong>\n<ul class=\"fig-list\"><li><code>Power Up Sequence</code>\n</li><li><code>Wakeup Sequence</code>\n</li><li><code>Run Sequence II</code> (über Notiz als „Corresponds to RUN II“ annotiert)\n</li><li><code>Run Sequence III</code> (über Notiz als „Corresponds to RUN III` annotiert)\n</li><li><code>Shutdown Sequence</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Eintritt (<code>alt Entry of RUN</code>):</strong>\n<ul class=\"fig-list\"><li>Zweig <code>[from STARTUP]</code>: Ausführung der Referenz <code>Power Up Sequence</code>, die synchron in eine kurze Aktivierung des EcuM übergeht.\n</li><li>Zweig <code>[from WAKEUP]</code>: Ausführung der Referenz <code>Wakeup Sequence</code>, die in die Hauptaktivierung des EcuM im RUN-Zustand mündet.\n</li></ul>\n</li><li><strong>Hauptschleife (<code>loop While RUN requests pending</code>):</strong>\n<ul class=\"fig-list\"><li>Solange RUN-Anforderungen anstehen, führt der EcuM synchron den Aufruf <code>call()</code> zur Referenzsequenz <code>Run Sequence II</code> aus und empfängt die Rückkehr.\n</li><li>Anschließend erfolgt der synchrone Aufruf <code>call()</code> zur Referenzsequenz <code>Run Sequence III</code> mit Rückkehr.\n</li></ul>\n</li><li><strong>Verlassen des RUN-Zustands:</strong>\n<ul class=\"fig-list\"><li>Nach Verlassen der Schleife geht der EcuM über <code>continue with()</code> direkt in die Referenz <code>Shutdown Sequence</code> über.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die übergeordnete Kontrollflussstruktur des EcuM im RUN-Zustand rein intern auf Modulebene ohne explizite Interaktionspartner. Die Fortführung in den Shutdown setzt voraus, dass keine RUN-Requests mehr anhängig sind. Die referenzierten Sequenzen RUN II und RUN III werden in separaten Sub-Sequenzdiagrammen detailliert.</p>"}], "trans": [{"from": "FIG-13db19d454506a09", "to": "FIG-ef066f3b0575df3a", "fr": "R2.1.20", "tr": "R3.0.7", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Interaktionspartner und Aufruf entfernt: Die Lebenslinie <code>RTE::RTE</code> sowie der synchrone RTE-Aufruf <code>RTE_Write_NotifyMode_ModeIndex(Instance, RUN)</code> mit Rückkehrpfeil wurden vollständig aus der Schleife entfernt.\n</li><li>Stereotyp ergänzt: Der Kopf der verbleibenden Lebenslinie <code>EcuM::EcuM</code> ist mit dem Stereotyp <code>«module»</code> ausgezeichnet.\n</li><li>Diagrammrahmen entfernt: Der äußere UML-Rahmen <code>sd Run Sequence</code> wurde entfernt.\n</li><li>Operationsaufrufe formalisiert: Die Transitionen zu den Interaktionsreferenzen <code>Run Sequence II</code>, <code>Run Sequence III</code> und <code>Shutdown Sequence</code> tragen nun Klammern (<code>call()</code>, <code>call()</code>, <code>continue with()</code>).\n</li><li>Schleifenbeschriftung geändert: Wording im Schleifenkopf von <code>loop while Run requests pending</code> zu <code>loop While RUN requests pending</code>.\n</li></ul>"}, {"from": "FIG-ef066f3b0575df3a", "to": "FIG-2e8eec89d8f7369c", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Diagrammrahmen hinzugefügt: Äußerer Sequenzdiagramm-Rahmen mit Bezeichner <code>sd EcuM_Run Sequence</code> ergänzt.\n</li><li>Lebenslinien-Bezeichner vereinfacht: Modulbezeichnung im Kopf von <code>EcuM::EcuM</code> auf <code>EcuM</code> verkürzt.\n</li></ul>"}]};
